// Domain model ↔ REST contract tests (prompt 65).
//
// Every fixture under test/fixtures/ is a REAL response envelope captured from
// the live PHP controllers in flavor-core/includes/API (generated by driving
// them against the mock WP environment — no hand-written JSON). The tests pin
// the model layer to that contract: field names, null-safety for fields the
// API can send as null/false, and lenient numeric parsing (ints, doubles and
// numeric strings).
import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart' show Color;
import 'package:flutter_test/flutter_test.dart';
import 'package:flavor_mobile/models/app_bootstrap_model.dart';
import 'package:flavor_mobile/models/branch_model.dart';
import 'package:flavor_mobile/models/calendar_model.dart';
import 'package:flavor_mobile/models/cart_model.dart';
import 'package:flavor_mobile/models/category_model.dart';
import 'package:flavor_mobile/models/dish_model.dart';
import 'package:flavor_mobile/models/json_fields.dart';
import 'package:flavor_mobile/models/order_model.dart';
import 'package:flavor_mobile/models/reservation_model.dart';
import 'package:flavor_mobile/models/review_model.dart';
import 'package:flavor_mobile/models/token_model.dart';
import 'package:flavor_mobile/models/user_model.dart';

Map<String, dynamic> envelope(String name) =>
    jsonDecode(File('test/fixtures/$name.json').readAsStringSync()) as Map<String, dynamic>;

dynamic fixtureData(String name) => envelope(name)['data'];

Map<String, dynamic> fixtureMap(String name) => fixtureData(name) as Map<String, dynamic>;

List<dynamic> fixtureList(String name) => fixtureData(name) as List<dynamic>;

Map<String, dynamic> firstOf(String name) => fixtureList(name).first as Map<String, dynamic>;

void main() {
  group('Response envelope contract', () {
    test('every fixture is a success envelope with data + meta + errors', () {
      const names = [
        'app_bootstrap', 'branches', 'tables', 'zones', 'categories', 'menu',
        'dish_detail', 'cart', 'cart_add_item', 'cart_update_item',
        'auth_otp_verify', 'token_refresh', 'order_create', 'orders_list',
        'order_detail', 'order_track', 'user_profile', 'review_submit',
        'dish_reviews', 'reviews_recent', 'reservation_slots',
        'reservation_book', 'reservation_row',
      ];
      for (final name in names) {
        final env = envelope(name);
        expect(env['success'], true, reason: name);
        expect(env['errors'], isEmpty, reason: name);
        expect(env['data'], isNotNull, reason: name);
        expect((env['meta'] as Map<String, dynamic>)['timestamp'], isA<int>(), reason: name);
      }
    });
  });

  group('json_fields helpers (PHP payload quirks)', () {
    test('strField maps PHP false leaks and nulls to the fallback', () {
      expect(strField('https://x/img.png'), 'https://x/img.png');
      expect(strField(false), '');
      expect(strField(null), '');
      expect(strField(null, 'fallback'), 'fallback');
      expect(strField(42), '42');
    });

    test('intField accepts ints, doubles and numeric strings', () {
      expect(intField(7), 7);
      expect(intField(7.0), 7);
      expect(intField('7'), 7);
      expect(intField('7.50'), 8);
      expect(intField(7.5), 8);
      expect(intField(null, 3), 3);
      expect(intField(false, 3), 3);
      expect(intField('abc', 9), 9);
    });

    test('doubleField and nullable variants keep null semantics', () {
      expect(doubleField('12.25'), 12.25);
      expect(doubleField(3), 3.0);
      expect(doubleField(null, 1.5), 1.5);
      expect(nullableDoubleField(null), isNull);
      expect(nullableDoubleField('35.7'), 35.7);
      expect(nullableIntField(null), isNull);
      expect(nullableIntField('12'), 12);
    });

    test('boolField only trusts explicit true', () {
      expect(boolField(true), isTrue);
      expect(boolField(false), isFalse);
      expect(boolField(null), isFalse);
      expect(boolField(null, whenNull: true), isTrue);
      expect(boolField('yes'), isFalse);
    });
  });

  group('TokenModel (auth fixtures)', () {
    test('parses the OTP verify token pair', () {
      final tokens = fixtureMap('auth_otp_verify')['tokens'] as Map<String, dynamic>;
      final token = TokenModel.fromJson(tokens);
      expect(token.tokenType, 'Bearer');
      expect(token.accessToken.length, 64);
      expect(token.refreshToken.length, 64);
      expect(token.expiresIn, 7200);
      expect(token.userId, 302);
      expect(token.expiresAt, isNotEmpty);
    });

    test('parses the refresh rotation payload including absolute expiry', () {
      final token = TokenModel.fromJson(fixtureMap('token_refresh'));
      expect(token.tokenType, 'Bearer');
      expect(token.expiresIn, 7200);
      expect(token.userId, 101);
      expect(RegExp(r'^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$').hasMatch(token.expiresAt),
          isTrue);
      final round = TokenModel.fromJson(token.toJson());
      expect(round.accessToken, token.accessToken);
      expect(round.expiresAt, token.expiresAt);
    });

    test('string numbers and missing keys degrade to safe defaults', () {
      final token = TokenModel.fromJson({'access_token': 'a', 'expires_in': '600'});
      expect(token.expiresIn, 600);
      final empty = TokenModel.fromJson({});
      expect(empty.tokenType, 'Bearer');
      expect(empty.expiresIn, 604800);
      expect(empty.userId, 0);
    });
  });

  group('CategoryModel', () {
    test('parses the full /categories payload', () {
      final raw = firstOf('categories');
      final category = CategoryModel.fromJson(raw);
      expect(category.id, 1);
      expect(category.name, 'کباب و گریل');
      expect(category.slug, 'kabab');
      expect(category.count, 8);
      expect(raw.keys, containsAll(['description', 'image', 'icon']));
    });

    test('dish-card category subset (id/name/slug only) fills defaults', () {
      final dishCards = fixtureList('menu');
      final cats = (dishCards.first as Map<String, dynamic>)['categories'] as List<dynamic>;
      for (final raw in cats.whereType<Map<String, dynamic>>()) {
        final category = CategoryModel.fromJson(raw);
        expect(category.id, greaterThan(0));
        expect(category.name, isNotEmpty);
        expect(category.description, '');
        expect(category.count, 0);
      }
    });
  });

  group('ReviewModel', () {
    test('parses an approved dish review row', () {
      final review = ReviewModel.fromJson(firstOf('dish_reviews'));
      expect(review.id, 1);
      expect(review.productId, 1);
      expect(review.authorName, 'علی رضایی');
      expect(review.rating, 5);
      expect(review.comment, contains('کباب'));
      expect(review.isVerified, isFalse);
      expect(review.date, isNotEmpty);
      expect(review.jalaliDate, contains('مهر'));
