    test('recent reviews carry dish_name/dish_image decorations', () {
      final review = ReviewModel.fromJson(firstOf('reviews_recent'));
      expect(review.dishName, 'چلو کباب کوبیده مخصوص زعفرانی');
      expect(review.dishImage, startsWith('https://'));
    });

    test('submit response ({id,is_verified}) parses through the same model', () {
      final review = ReviewModel.fromJson(fixtureMap('review_submit'));
      expect(review.id, 1);
      expect(review.isVerified, isFalse);
    });
  });

  group('ReservationSlot', () {
    test('slots use the real key `free` — never the invented `remaining`', () {
      final slotsRaw = fixtureMap('reservation_slots')['slots'] as List<dynamic>;
      expect(slotsRaw, isNotEmpty);
      for (final raw in slotsRaw.whereType<Map<String, dynamic>>()) {
        expect(raw.containsKey('free'), isTrue);
        expect(raw.containsKey('remaining'), isFalse);
      }
      final slot = ReservationSlot.fromJson(slotsRaw.first as Map<String, dynamic>);
      expect(slot.time, '12:00');
      expect(slot.timeSql, '12:00:00');
      expect(slot.available, isTrue);
      expect(slot.free, 18);
      expect(slot.toJson()['free'], 18);
    });

    test('unavailable/edge slots parse without crashing', () {
      final slot = ReservationSlot.fromJson({
        'time': '23:30',
        'available': false,
        'free': 0,
      });
      expect(slot.available, isFalse);
      expect(slot.free, 0);
      final bare = ReservationSlot.fromJson({});
      expect(bare.available, isTrue); // absent = not explicitly closed
      expect(bare.free, 0);
    });
  });

  group('ReservationModel', () {
    test('parses the raw DB row with its genuine nulls', () {
      final row = fixtureMap('reservation_row');
      final reservation = ReservationModel.fromJson(row);
      expect(reservation.id, 1);
      expect(reservation.branchId, 1);
      expect(reservation.tableId, isNull); // NULL column stays null
      expect(reservation.reservationDate, '2026-10-28');
      expect(reservation.reservationTime, '20:30:00');
      expect(reservation.reservationTimeShort, '20:30');
      expect(reservation.durationMinutes, 90);
      expect(reservation.partySize, 4);
      expect(reservation.customerId, 303);
      expect(reservation.customerName, 'مهدی کمالی');
      expect(reservation.customerMobile, '09127776655');
      expect(reservation.section, 'indoor');
      expect(reservation.status, 'pending');
      expect(reservation.specialRequests, 'میز نزدیک پنجره');
      expect(reservation.source, 'online');
      expect(reservation.isUpcoming, isTrue);
      expect(reservation.jalali, isNotNull);
      expect(reservation.jalali!.year, 1405);
      expect(reservation.jalali!.iso, '1405-08-06');
      expect(reservation.jalaliLabel, contains('آبان'));
    });

    test('booking response (date/time aliases) parses through fallbacks', () {
      final booking = fixtureMap('reservation_book');
      final reservation = ReservationModel.fromJson(booking);
      expect(reservation.id, 1);
      expect(reservation.reservationDate, '2026-10-28');
      expect(reservation.reservationTime, '20:30');
      expect(reservation.status, 'pending');
      expect(reservation.jalaliLabel, isNotEmpty);
    });

    test('null section/special_requests fall back to safe defaults', () {
      final reservation = ReservationModel.fromJson({
        'id': '55',
        'section': null,
        'special_requests': null,
        'status': 'confirmed',
      });
      expect(reservation.id, 55); // string id parses
      expect(reservation.section, 'indoor');
      expect(reservation.specialRequests, '');
      expect(reservation.isUpcoming, isTrue);
    });
  });

  group('DiningTable / DeliveryZone / BranchModel', () {
    test('tables match the BranchController serializer', () {
      final table = DiningTable.fromJson(firstOf('tables'));
      expect(table.id, 1);
      expect(table.tableNumber, 'T-01');
      expect(table.label, 'میز پنجره ۱');
      expect(table.capacity, 4);
      expect(table.section, 'window');
      expect(table.qrToken, 'qr_token_1');
      expect(table.qrUrl, contains('/table/T-01/'));
    });

    test('zone radius_km is a genuine API null and stays nullable', () {
      final raw = firstOf('zones');
      expect(raw.containsKey('radius_km'), isTrue);
      final zone = DeliveryZone.fromJson(raw);
      expect(zone.id, 1);
      expect(zone.name, 'منطقه ونک و مرکز تهران');
      expect(zone.zoneType, 'neighborhoods');
      expect(zone.radiusKm, isNull);
      expect(zone.deliveryFee, 25000);
      expect(zone.deliveryFeeHtml, contains('تومان'));
      expect(zone.minOrder, 100000);
      expect(zone.neighborhoods, ['تهران', 'ونک', 'ملاصدرا']);
      // A radius zone sends a number (or numeric string) instead:
      final radiusZone = DeliveryZone.fromJson({'id': 2, 'radius_km': '7.5'});
      expect(radiusZone.radiusKm, 7.5);
    });

    test('branch cards expose timezone + permalink + card-only fields', () {
      final branch = BranchModel.fromJson(firstOf('branches'));
      expect(branch.id, 1);
      expect(branch.name, 'شعبه مرکزی شاندیز');
      expect(branch.slug, 'central-branch');
      expect(branch.timezone, 'Asia/Tehran');
      expect(branch.orderModes, ['dine_in', 'takeaway', 'delivery']);
      expect(branch.isOpen, isTrue);
      expect(branch.lat, ''); // unset coordinate arrives as '' string
      expect(branch.permalink, isNotEmpty);
    });

    test('bootstrap branches omit thumbnail/is_open — defaults kick in', () {
      final raw = (fixtureMap('app_bootstrap')['branches'] as List<dynamic>).first
          as Map<String, dynamic>;
      expect(raw.containsKey('thumbnail'), isFalse);
      expect(raw.containsKey('is_open'), isFalse);
      final branch = BranchModel.fromJson(raw);
      expect(branch.thumbnail, '');
      expect(branch.isOpen, isTrue);
      expect(branch.menuVersion, greaterThanOrEqualTo(1));
    });

    test('branch detail merges card + description/zones_count/opening_hours', () {
      final raw = fixtureMap('branch_detail');
      expect(raw.keys, containsAll(['description', 'zones_count', 'opening_hours']));
      final branch = BranchModel.fromJson(raw);
      expect(branch.id, 1);
    });
  });

  group('DishModel + modifier groups', () {
    test('menu card payload parses with detail-only keys defaulted', () {
      final dish = DishModel.fromJson(firstOf('menu'));
      expect(dish.id, 1);
      expect(dish.name, 'چلو کباب کوبیده مخصوص زعفرانی');
      expect(dish.price, 2800000); // storage unit (IRR)
      expect(dish.priceHtml, contains('تومان'));
      expect(dish.ratingAvg, 4.9); // PHP float survives
      expect(dish.ratingCount, 120);
      expect(dish.available, isTrue);
      expect(dish.hasModifiers, isTrue);
      expect(dish.allergens, isEmpty);
      expect(dish.dietary, isEmpty);
      // Card payload has no detail keys:
      expect(dish.description, '');
      expect(dish.gallery, isEmpty);
      expect(dish.modifierGroups, isEmpty);
      expect(dish.sku, '');
    });

    test('dish detail carries sku, description and three modifier groups', () {
      final raw = fixtureMap('dish_detail');
      final dish = DishModel.fromJson(raw);
      expect(dish.sku, 'DISH-1');
      expect(dish.description, contains('توضیحات کامل'));
      expect(raw.keys, containsAll(['gallery', 'schedules', 'allergens']));
      expect(dish.modifierGroups.length, 3);

      final size = dish.modifierGroups.firstWhere((g) => g.type == 'size');
      expect(size.required, isTrue);
      expect(size.multi, isFalse);
      expect(size.options.single.id, 'size-large');
      expect(size.options.single.price, 50000);
      expect(size.options.single.priceHtml, startsWith('+'));

      final topping = dish.modifierGroups.firstWhere((g) => g.type == 'topping');
      expect(topping.multi, isTrue);
      expect(topping.required, isFalse);

      final removal = dish.modifierGroups.firstWhere((g) => g.type == 'removal');
      // Zero-price options are labeled «رایگان» server-side.
      expect(removal.options.single.price, 0);
      expect(removal.options.single.priceHtml, 'رایگان');
    });

    test('string numbers and false images degrade safely', () {
      final dish = DishModel.fromJson({
        'id': '77',
        'price': '1250000',
        'regular_price': '1500000.0',
        'rating_avg': '3.25',
        'image': false, // PHP wp_get_attachment_image_url() leak
      });
      expect(dish.id, 77);
      expect(dish.price, 1250000);
      expect(dish.regularPrice, 1500000);
      expect(dish.ratingAvg, 3.25);
      expect(dish.image, '');
      expect(dish.discountPct, 0);
    });
  });

  group('CartItem / CartModel', () {
    test('cart payload exposes authoritative storage numerics per line', () {
      final cart = CartModel.fromJson(fixtureMap('cart'));
      expect(cart.count, 2);
      expect(cart.items.length, 1);
      final line = cart.items.first;
      expect(line.productId, 1);
      expect(line.quantity, 2);
      expect(line.unitPriceRaw, 287500.0); // catalog float incl. extras
      expect(line.lineTotalRaw, 575000.0);
      expect(line.unitPrice, 2875000); // storage int
      expect(line.lineTotal, 5750000);
      expect(line.unitPriceHtml, contains('تومان'));
      expect(line.lineTotalHtml, contains('تومان'));
      expect(line.priceHtml, isNotEmpty); // legacy labels still present
      expect(line.lineHtml, isNotEmpty);
      expect(line.key.length, 32); // hashed selection key
      expect(line.instructions, 'لطفاً سماق قرمز جداگانه ارسال شود.');
    });

    test('line modifiers are the sanitized selection rows', () {
      final line = CartModel.fromJson(fixtureMap('cart')).items.first;
      expect(line.modifiers.length, 2);
      expect(line.modifiers[0].id, 'size-large');
      expect(line.modifiers[0].type, 'size');
      expect(line.modifiers[0].typeLabel, 'اندازه');
      expect(line.modifiers[0].price, 50000);
      expect(line.modifiers[1].id, 'extra_rice');
      expect(line.modifiers[1].typeLabel, 'تاپینگ');
    });

    test('cart totals breakdown + capability flag', () {
      final cart = CartModel.fromJson(fixtureMap('cart'));
      expect(cart.subtotal, 5750000);
      expect(cart.subtotalHtml, '۵۷۵,۰۰۰ تومان');
      expect(cart.total, 5750000);
      expect(cart.totalHtml, '۵۷۵,۰۰۰ تومان');
      expect(cart.discountTotal, 0);
      expect(cart.taxTotal, 0);
      expect(cart.shippingTotal, 0);
      expect(cart.fees, isEmpty);
      expect(cart.coupons, isEmpty);
      expect(cart.pointsToEarn, 57);
      expect(cart.needsPayment, isTrue);
      expect(cart.supportsItemEdit, isTrue);
    });

    test('item edit re-prices the line (update_item fixture)', () {
      final cart = CartModel.fromJson(fixtureMap('cart_update_item'));
      final line = cart.items.first;
      expect(line.quantity, 3);
      expect(line.modifiers.length, 1);
      expect(line.modifiers.single.id, 'size-large');
      expect(line.unitPriceRaw, 285000.0);
      expect(line.lineTotal, 8550000);
      expect(cart.total, 8550000);
    });

    test('legacy {ids:[]} modifier map and false image do not crash', () {
      final item = CartItem.fromJson({
        'key': 'k',
        'product_id': 3,
        'name': 'x',
        'quantity': 1,
        'price_html': '',
        'line_html': '',
        'modifiers': {'ids': <String>[]},
        'image': false,
      });
      expect(item.modifiers, isEmpty);
      expect(item.image, '');
    });
  });

