  group('AppBootstrapModel', () {
    test('brand/design/currency blocks', () {
      final bootstrap = AppBootstrapModel.fromJson(fixtureMap('app_bootstrap'));
      expect(bootstrap.app.name, 'رستوران سنتی شاندیز');
      expect(bootstrap.app.description, isNotEmpty);
      expect(bootstrap.app.phone, '021-12345678');
      expect(bootstrap.app.maintenanceMode, isFalse);
      expect(bootstrap.app.minAppVersion, '1.0.0');
      expect(bootstrap.design.preset, 'modern_restaurant');
      expect(bootstrap.design.primaryColor, const Color(0xFFC8102E));
      expect(bootstrap.design.accentColor, const Color(0xFFD97706));
      expect(bootstrap.design.fontFamily, 'iransans');
      expect(bootstrap.design.borderRadius, 12.0); // "0.75rem" → px
      expect(bootstrap.currency.storageUnit, 'irr');
      expect(bootstrap.currency.displayUnit, 'irt');
      expect(bootstrap.currency.label, 'تومان');
      expect(bootstrap.currency.decimals, 0);
    });

    test('auth + calendar + ordering blocks (newly aligned)', () {
      final bootstrap = AppBootstrapModel.fromJson(fixtureMap('app_bootstrap'));
      expect(bootstrap.auth.otpLength, 5);
      expect(bootstrap.auth.otpResendSec, 120);
      expect(RegExp(r'^\d{4}-\d{2}-\d{2}$').hasMatch(bootstrap.calendar.gregorianToday),
          isTrue);
      expect(bootstrap.calendar.jalaliToday.year, inInclusiveRange(1400, 1500));
      expect(bootstrap.calendar.jalaliToday.iso, isNotEmpty);
      expect(bootstrap.calendar.jalaliLabel, isNotEmpty);
      expect(bootstrap.orderingModes.length, 3);
      expect(bootstrap.orderingModes.map((m) => m.id).toList(),
          ['dine_in', 'takeaway', 'delivery']);
      expect(bootstrap.orderingModes.first.label, isNotEmpty);
      expect(bootstrap.orderingModes.first.icon, 'utensils');
      expect(bootstrap.guestCheckout, isTrue);
    });

    test('branches + default branch id', () {
      final bootstrap = AppBootstrapModel.fromJson(fixtureMap('app_bootstrap'));
      expect(bootstrap.branches, isNotEmpty);
      expect(bootstrap.defaultBranchId, 1);
      expect(bootstrap.branches.first.timezone, 'Asia/Tehran');
    });

    test('JalaliDateInfo handles the shared {y,m,d,iso,label} shape', () {
      final raw = fixtureMap('reservation_row')['jalali'] as Map<String, dynamic>;
      final info = JalaliDateInfo.fromJson(raw);
      expect(info.year, 1405);
      expect(info.month, 8);
      expect(info.day, 6);
      expect(info.iso, '1405-08-06');
      expect(info.label, '6 آبان 1405');
      expect(JalaliDateInfo.fromJson(null).year, 0);
      expect(info.toJson()['y'], 1405);
    });
  });
